import random
import string
from typing import List

# Data type: arbitrary string
# Used by fuzzer stubs as:
# - sixel_helper_set_additional_message(msg.c_str())
# - sixel_encoder_setopt(..., optarg)
# - sixel_decoder_setopt(..., optarg)
# Goal: generate interesting but valid C strings (including NUL-free payload since C API uses c_str()).
# We must return a bytes buffer that the fuzzing framework will slice for FUZZ_PARAM_STR/FILENAME.
# We'll produce a corpus of diverse strings concatenated with a simple delimiter so consumers can
# split or use prefixes. However, many fuzzers just take the whole buffer for one FUZZ_PARAM_STR.
# Therefore, we generate a single interesting string payload per call, varying content.

MAX_LEN = 1024

# Common interesting substrings for options/messages in libsixel context
OPT_like_snippets: List[str] = [
    "-o", "--output=", "--quality=high", "--quality=low", "--high-color",
    "--palette=hls", "--palette=rgb", "--dither=fs", "--dither=atkinson",
    "--res=nearest", "--res=lanczos3", "--width=80", "--height=24",
    "--colors=16", "--colors=256", "--transparent=0", "--skipdcs",
    "--8bit", "--7bit", "--fast", "--size",
]

# Interesting unicode and control sequences (excluding NUL) that are still valid as bytes
CONTROL_BYTES = [
    0x01, 0x02, 0x03, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x1B
]

PRINT_BYTES = list((ord(c) for c in string.ascii_letters + string.digits + string.punctuation + " "))

def rand_printable(r: random.Random, n: int) -> bytes:
    return bytes(r.choice(PRINT_BYTES) for _ in range(n))

def rand_controls(r: random.Random, n: int) -> bytes:
    return bytes(r.choice(CONTROL_BYTES) for _ in range(n))

def encode_str(s: str) -> bytes:
    return s.encode('utf-8', 'ignore')

def build_message(r: random.Random) -> bytes:
    # Compose a message with a prefix, optional controls, and suffix
    parts: List[bytes] = []
    # Optional human text
    phrases = [
        "libsixel fuzz seed", "note", "warning", "error detail", "optarg",
        "доп", "メッセージ", "消息", "mensaje", "msg"
    ]
    parts.append(encode_str(r.choice(phrases)))
    # Maybe add colon and space
    if r.random() < 0.7:
        parts.append(b": ")
    # Add some option-like snippet or random printable chunk
    if r.random() < 0.6:
        parts.append(encode_str(r.choice(OPT_like_snippets)))
        if r.random() < 0.5:
            # attach a numeric or value
            val = str(r.randint(0, 1024)) if r.random() < 0.5 else r.choice([
                "auto", "fast", "size", "rgb", "hls", "fs", "atkinson"
            ])
            if not parts[-1].endswith(b"=") and r.random() < 0.7:
                parts.append(b"=")
            parts.append(encode_str(val))
    else:
        parts.append(rand_printable(r, r.randint(5, 40)))
    # Sprinkle controls
    if r.random() < 0.8:
        parts.append(rand_controls(r, r.randint(0, 6)))
    # Possibly add long tail of random bytes (printable) to vary length
    if r.random() < 0.5:
        parts.append(rand_printable(r, r.randint(0, 200)))
    out = b"".join(parts)
    # Truncate to MAX_LEN and ensure no embedded NUL to be safe for c_str() length-sensitive code
    out = out.replace(b"\x00", b"_")
    if len(out) == 0:
        out = b"msg"
    return out[:MAX_LEN]

def build_option_string(r: random.Random) -> bytes:
    # Generate strings suitable for setopt: either empty (flags-only) or key=value or numeric
    choice = r.random()
    if choice < 0.2:
        return b""  # flags without arguments
    elif choice < 0.5:
        key = r.choice([
            "colors", "palette", "dither", "quality", "encode-policy",
            "width", "height", "loop", "transparent", "resample"
        ])
        if key in ("width", "height", "colors", "transparent"):
            val = str(r.randint(0, 512))
        elif key == "quality":
            val = r.choice(["auto", "high", "low", "full", "highcolor"])
        elif key == "palette":
            val = r.choice(["rgb", "hls"])    
        elif key == "dither":
            val = r.choice(["none", "fs", "atkinson", "stucki", "burkes"])    
        elif key == "encode-policy":
            val = r.choice(["auto", "fast", "size"])    
        else:
            val = r.choice(["nearest", "bilinear", "lanczos3"])    
        s = f"{key}={val}"
        return encode_str(s)
    else:
        # Free-form string with possible control bytes
        base = build_message(r)
        return base[:MAX_LEN]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide which consumer we are targeting in this call to diversify corpus
    mode = r.choice(["message", "opt", "opt", "opt-empty", "opt-numeric"])  # weight toward options
    if mode == "message":
        buf = build_message(r)
    elif mode == "opt-empty":
        buf = b""  # exercise flags that ignore optarg
    elif mode == "opt-numeric":
        # Pure numeric string
        num = str(r.randint(0, 10_000))
        buf = num.encode('ascii')
    else:  # "opt"
        buf = build_option_string(r)

    # Ensure upper size bound and NUL-free
    buf = buf.replace(b"\x00", b"_")
    if len(buf) > 4096:
        buf = buf[:4096]
    # Guarantee non-empty for APIs that expect some string; if empty chosen, keep it for flags-only paths
    return bytes(buf)
